"""Load application config from a JSON file, falling back to built-in defaults."""

import json
import logging
import os
from copy import deepcopy

logger = logging.getLogger(__name__)

DEFAULT_CONFIG = {
    "host": "127.0.0.1",
    "port": 8080,
    "debug": False,
    "log_level": "INFO",
    "database": {
        "url": "sqlite:///app.db",
        "pool_size": 5,
    },
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be used."""


def _merge(base, override):
    """Recursively overlay override onto base, returning a new dict."""
    result = deepcopy(base)
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = _merge(result[key], value)
        else:
            result[key] = value
    return result


def load_config(path=None, defaults=None):
    """Return the config at `path` merged over `defaults`.

    A missing file is not an error: the defaults are returned unchanged.
    A malformed or unreadable file raises ConfigError, since silently
    ignoring it would hide a typo behind seemingly working defaults.
    """
    if defaults is None:
        defaults = DEFAULT_CONFIG
    if path is None:
        path = os.environ.get("APP_CONFIG", "config.json")

    try:
        with open(path, encoding="utf-8") as fh:
            loaded = json.load(fh)
    except FileNotFoundError:
        logger.info("No config at %s; using defaults", path)
        return deepcopy(defaults)
    except OSError as exc:
        raise ConfigError(f"cannot read config {path}: {exc}") from exc
    except json.JSONDecodeError as exc:
        raise ConfigError(f"invalid JSON in {path}: {exc}") from exc

    if not isinstance(loaded, dict):
        raise ConfigError(f"{path} must contain a JSON object, got {type(loaded).__name__}")

    return _merge(defaults, loaded)
